const entries = document.querySelector('[data-ai4a11y-entries]');
if (entries) return false;
const skipButtons = document.querySelectorAll('.ai4a11y-entry');
if (skipButtons.length > 0) return false;
const existing = document.getElementById('existing-skip-link');
if (!existing) return false;
return true;

const btn = document.getElementById('btn-action');
if (!btn) return false;
btn.focus();
const st = window.getComputedStyle(btn);
const hasOutline = parseFloat(st.outlineWidth) >= 2;
const hasShadow = st.boxShadow.includes('rgb(26, 95, 180)');
btn.blur();
return hasOutline || hasShadow;

const existing = document.getElementById('existing-skip-link');
